// pll_sys: the compiled PLL mode. Default NTSC 352 (pll_sys.v); the build-only POCKET_PLL_COMPILE_320 takes NTSC 320
// (pll_sys_320.v). Both are generated by tools/gen_pll_sys.sh and keep the module name pll_sys, so the qsf counter
// locations and the SDC clock names apply to either. docs/integration.md section 2.
`ifdef POCKET_PLL_COMPILE_320
`include "pll_sys_320.v"
`else
`include "pll_sys.v"
`endif
